def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    # Find the row containing the encoded multi-cell pattern.
    template_row = None
    for r, row in enumerate(grid):
        cells = [v for v in row if v != bg]
        if len(cells) >= 3 and len(set(cells)) > 1:
            template_row = r
            break

    row = grid[template_row]
    positions = [c for c, v in enumerate(row) if v != bg]
    lo, hi = min(positions), max(positions)
    pattern = row[lo:hi + 1]
    width = len(pattern)

    out = [r[:] for r in grid]
    for r in range(h):
        if r == template_row:
            continue
        for c, v in enumerate(grid[r]):
            if v == 6:
                start = c - width // 2
                for i, color in enumerate(pattern):
                    x = start + i
                    if 0 <= x < w:
                        out[r][x] = color
    return out
